void
fd_event_runtime_epoch_serialize( fd_circq_t *                     circq,
                                  fd_event_client_t *              client,
                                  long                             timestamp_nanos,
                                  ulong                            link_seq,
                                  fd_event_runtime_epoch_t const * msg ) {
  uchar * buffer = fd_circq_push_back( circq, 1UL, FD_EVENT_RUNTIME_EPOCH_BUF_MAX );
  FD_TEST( buffer );

  ulong event_id = fd_event_client_id_reserve( client );

  fd_pb_encoder_t encoder[1];
  fd_pb_encoder_init( encoder, buffer, FD_EVENT_RUNTIME_EPOCH_BUF_MAX );

  FD_TEST( circq->cursor_push_seq );
  fd_pb_push_uint64( encoder, 1U, circq->cursor_push_seq-1UL );
  fd_pb_push_uint64( encoder, 2U, event_id );
  fd_pb_push_uint64( encoder, 3U, link_seq );
  fd_pb_push_uint64( encoder, 4U, (ulong)timestamp_nanos );

  FD_TEST( msg->stake_history_sysvar_cnt<=1UL );
  FD_TEST( msg->epoch_schedule_sysvar_cnt<=1UL );
  FD_TEST( msg->feature_activations_cnt<=16UL );
  FD_TEST( msg->epoch_rewards_sysvar_cnt<=1UL );

  fd_pb_submsg_open( encoder, 5U ); /* Event */
  fd_pb_submsg_open( encoder, 13U ); /* RuntimeEpoch */
  if( msg->bank_seq ) fd_pb_push_uint64( encoder, 1U, (ulong)msg->bank_seq );
  if( msg->slot ) fd_pb_push_uint64( encoder, 2U, (ulong)msg->slot );
  if( msg->parent_slot ) fd_pb_push_uint64( encoder, 3U, (ulong)msg->parent_slot );
  if( msg->epoch ) fd_pb_push_uint64( encoder, 4U, (ulong)msg->epoch );
  if( msg->total_effective_stake ) fd_pb_push_uint64( encoder, 5U, (ulong)msg->total_effective_stake );
  if( msg->total_activating_stake ) fd_pb_push_uint64( encoder, 6U, (ulong)msg->total_activating_stake );
  if( msg->total_deactivating_stake ) fd_pb_push_uint64( encoder, 7U, (ulong)msg->total_deactivating_stake );
  if( msg->total_epoch_stake ) fd_pb_push_uint64( encoder, 8U, (ulong)msg->total_epoch_stake );
  if( msg->num_staked_vote_accounts ) fd_pb_push_uint64( encoder, 9U, (ulong)msg->num_staked_vote_accounts );
  if( msg->num_vote_accounts ) fd_pb_push_uint64( encoder, 10U, (ulong)msg->num_vote_accounts );
  if( msg->num_top_votes_eligible ) fd_pb_push_uint64( encoder, 11U, (ulong)msg->num_top_votes_eligible );
  if( msg->top_votes_min_stake ) fd_pb_push_uint64( encoder, 12U, (ulong)msg->top_votes_min_stake );
  for( ulong k=0UL; k<msg->stake_history_sysvar_cnt; k++ ) {
    fd_pb_submsg_open( encoder, 13U );
    if( msg->stake_history_sysvar[ k ].epoch ) fd_pb_push_uint64( encoder, 1U, (ulong)msg->stake_history_sysvar[ k ].epoch );
    if( msg->stake_history_sysvar[ k ].effective ) fd_pb_push_uint64( encoder, 2U, (ulong)msg->stake_history_sysvar[ k ].effective );
    if( msg->stake_history_sysvar[ k ].activating ) fd_pb_push_uint64( encoder, 3U, (ulong)msg->stake_history_sysvar[ k ].activating );
    if( msg->stake_history_sysvar[ k ].deactivating ) fd_pb_push_uint64( encoder, 4U, (ulong)msg->stake_history_sysvar[ k ].deactivating );
    fd_pb_submsg_close( encoder );
  }
  for( ulong k=0UL; k<msg->epoch_schedule_sysvar_cnt; k++ ) {
    fd_pb_submsg_open( encoder, 14U );
    if( msg->epoch_schedule_sysvar[ k ].slots_per_epoch ) fd_pb_push_uint64( encoder, 1U, (ulong)msg->epoch_schedule_sysvar[ k ].slots_per_epoch );
    if( msg->epoch_schedule_sysvar[ k ].leader_schedule_slot_offset ) fd_pb_push_uint64( encoder, 2U, (ulong)msg->epoch_schedule_sysvar[ k ].leader_schedule_slot_offset );
    if( msg->epoch_schedule_sysvar[ k ].warmup ) fd_pb_push_bool  ( encoder, 3U, msg->epoch_schedule_sysvar[ k ].warmup );
    if( msg->epoch_schedule_sysvar[ k ].first_normal_epoch ) fd_pb_push_uint64( encoder, 4U, (ulong)msg->epoch_schedule_sysvar[ k ].first_normal_epoch );
    if( msg->epoch_schedule_sysvar[ k ].first_normal_slot ) fd_pb_push_uint64( encoder, 5U, (ulong)msg->epoch_schedule_sysvar[ k ].first_normal_slot );
    fd_pb_submsg_close( encoder );
  }
  for( ulong k=0UL; k<msg->feature_activations_cnt; k++ ) {
    fd_pb_push_bytes ( encoder, 15U, msg->feature_activations[ k ], 32UL );
  }
  for( ulong k=0UL; k<msg->epoch_rewards_sysvar_cnt; k++ ) {
    fd_pb_submsg_open( encoder, 16U );
    if( msg->epoch_rewards_sysvar[ k ].total_rewards ) fd_pb_push_uint64( encoder, 1U, (ulong)msg->epoch_rewards_sysvar[ k ].total_rewards );
    if( msg->epoch_rewards_sysvar[ k ].distributed ) fd_pb_push_uint64( encoder, 2U, (ulong)msg->epoch_rewards_sysvar[ k ].distributed );
    if( msg->epoch_rewards_sysvar[ k ].distribution_starting_block_height ) fd_pb_push_uint64( encoder, 3U, (ulong)msg->epoch_rewards_sysvar[ k ].distribution_starting_block_height );
    if( msg->epoch_rewards_sysvar[ k ].num_partitions ) fd_pb_push_uint64( encoder, 4U, (ulong)msg->epoch_rewards_sysvar[ k ].num_partitions );
    if( msg->epoch_rewards_sysvar[ k ].total_points ) fd_pb_push_bytes ( encoder, 5U, (uchar const *)&msg->epoch_rewards_sysvar[ k ].total_points, 16UL );
    fd_pb_push_bytes ( encoder, 6U, msg->epoch_rewards_sysvar[ k ].parent_blockhash, 32UL );
    fd_pb_submsg_close( encoder );
  }
  fd_pb_submsg_close( encoder );
  fd_pb_submsg_close( encoder );
  fd_circq_resize_back( circq, fd_pb_encoder_out_sz( encoder ) );
}

