  if( msg->reward_commission_bps ) fd_pb_push_uint32( encoder, 12U, (uint)msg->reward_commission_bps );
  if( msg->credits ) fd_pb_push_uint64( encoder, 13U, (ulong)msg->credits );
  if( msg->prev_credits ) fd_pb_push_uint64( encoder, 14U, (ulong)msg->prev_credits );
  if( msg->epoch_credits_cnt ) fd_pb_push_uint64( encoder, 15U, (ulong)msg->epoch_credits_cnt );
  fd_pb_submsg_close( encoder );
  fd_pb_submsg_close( encoder );
  fd_circq_resize_back( circq, fd_pb_encoder_out_sz( encoder ) );
