void
fd_event_serialize_by_type( ulong               type,
                            fd_circq_t *        circq,
                            fd_event_client_t * client,
                            long                timestamp_nanos,
                            ulong               link_seq,
                            void const *        ev,
                            ulong               ev_sz ) {
  switch( type ) {
  case 3UL:
    FD_TEST( ev_sz==sizeof(fd_event_signed_vote_t) );
    fd_event_signed_vote_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_signed_vote_t const *)ev );
    break;
  case 4UL:
    FD_TEST( ev_sz==sizeof(fd_event_slot_confirmed_t) );
    fd_event_slot_confirmed_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_slot_confirmed_t const *)ev );
    break;
  case 5UL:
    FD_TEST( ev_sz==sizeof(fd_event_accdb_compaction_completed_t) );
    fd_event_accdb_compaction_completed_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_accdb_compaction_completed_t const *)ev );
    break;
  case 6UL:
    FD_TEST( ev_sz==sizeof(fd_event_accdb_partition_added_t) );
    fd_event_accdb_partition_added_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_accdb_partition_added_t const *)ev );
    break;
  case 7UL:
    FD_TEST( ev_sz==sizeof(fd_event_block_equivocated_t) );
    fd_event_block_equivocated_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_block_equivocated_t const *)ev );
    break;
  case 8UL:
    FD_TEST( ev_sz==sizeof(fd_event_runtime_txn_t) );
    fd_event_runtime_txn_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_runtime_txn_t const *)ev );
    break;
  case 9UL:
    FD_TEST( ev_sz==sizeof(fd_event_runtime_block_t) );
    fd_event_runtime_block_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_runtime_block_t const *)ev );
    break;
  case 10UL:
    FD_TEST( ev_sz==sizeof(fd_event_runtime_reward_t) );
    fd_event_runtime_reward_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_runtime_reward_t const *)ev );
    break;
  case 11UL:
    FD_TEST( ev_sz==sizeof(fd_event_runtime_stake_delegation_t) );
    fd_event_runtime_stake_delegation_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_runtime_stake_delegation_t const *)ev );
    break;
  case 12UL:
    FD_TEST( ev_sz==sizeof(fd_event_runtime_rooted_t) );
    fd_event_runtime_rooted_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_runtime_rooted_t const *)ev );
    break;
  case 13UL:
    FD_TEST( ev_sz==sizeof(fd_event_runtime_epoch_t) );
    fd_event_runtime_epoch_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_runtime_epoch_t const *)ev );
    break;
  case 14UL:
    FD_TEST( ev_sz==sizeof(fd_event_runtime_vote_account_t) );
    fd_event_runtime_vote_account_serialize( circq, client, timestamp_nanos, link_seq, (fd_event_runtime_vote_account_t const *)ev );
    break;
  default: FD_LOG_ERR(( "unexpected event type %lu", type ));
  }
}
